registerRefData('nsw-cond-n-5539',{"id":5539,"pan":null,"ref":"56271/2019","address":"Lot: 103 Dp: 707503  290 Avoca Drive Kincumber  Nsw  2251","description":"NOMINATED INTEGRATED Residential 108 Bed Aged Care Facility (RPP)","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":null,"notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPS-2019HCC015!20200623T075741.947 GMT","sha256":"6efc5fff9a525bc4bc694f9cd61045982902943f4ae06bdc6620858e947458f1","pages":26,"layout":"numbered","n":11,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/5539.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/nominated-integrated-residential-108-bed-aged-care-facility-rpp","lga":"CENTRAL COAST","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPS-2019HCC015 - Central Coast - DA 56271/2019","stage":"general","stage_basis":"heading","page":5},{"label":"2","code":null,"number":"2","title":"PROPOSED DEVELOPMENT Nominated integrated residential 108 bed aged care facility at 88","text":"Scraysbrook Drive KINCUMBER (formerly known as 290 Avoca Drive\nKINCUMBER)","stage":"general","stage_basis":"heading","page":5},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 88 Scraysbrook Drive KINCUMBER","text":"","stage":"general","stage_basis":"heading","page":5},{"label":"4","code":null,"number":"4","title":"APPLICANT","text":"OWNER\nCatholic Healthcare\nLendlease Retirement Living Holding Pty Ltd","stage":"general","stage_basis":"heading","page":5},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT General development over $30 million","stage":"general","stage_basis":"heading","page":5},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n Roads Act 1993\n Rural Fires Act 1997\n Water Management Act 2000\n Water Management (General) Regulation 2011\n Environmental planning instruments:\no State Environmental Planning Policy No 55 - Remediation of\nLand\no State Environmental Planning Policy No 64 - Advertising and\nSignage\no State Environmental Planning Policy (Coastal Management)\n2018\no State Environmental Planning Policy (State and Regional\nDevelopment) 2011\no State Environmental Planning Policy (Infrastructure) 2007\no State Environmental Planning Policy (Housing for Seniors or\nPeople with a Disability (2004)\no Gosford Local Environmental Plan 2014\n Draft environmental planning instruments:\no Draft Central Coast Local Environmental Plan 2018\n Development control plans:\no Gosford Development Control Plan 2013\n Planning agreements: Nil\n Provisions of the Environmental Planning and Assessment\nRegulation 2000\n Coastal zone management plan: Nil\n The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and\neconomic impacts in the locality\n The suitability of the site for the development\n Any submissions made in accordance with the Environmental\nPlanning and Assessment Act 1979 or regulations\n The public interest, including the principles of ecologically\nsustainable development","stage":"general","stage_basis":"heading","page":5},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL  Council assessment report: 25 May 2020\n Clause 4.6 Exception to Development Standards - Clause 40(4)(a)\nHeight (8m) under State Environmental Planning Policy (Housing for\nSeniors or People with a Disability) 2004\n Clause 4.6 Exception to Development Standards - Clause 40(4)(b)\nHeight (2 storeys) under State Environmental Planning Policy\n(Housing for Seniors or People with a Disability) 2004\n Written submissions during public exhibition: 14\n Additional information memo: 15 June 2020\n Amended architecturals with notations\n Verbal submissions at the public meeting:\no Fiona Morrison, Ed McCarthy and Stephanie McCarthy\no Council assessment officer - Karen Hanratty\no On behalf of the applicant - Michael Lockwood, Karen\nArmstrong, Deb Robins, Simo Corda, Numa Miller and Sean\nMorgan","stage":"general","stage_basis":"heading","page":5},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n Briefing and site inspection: 4 March 2020\no Panel members: Alison McCabe (Chair), Sandra Hutton, Kyle\nMacGregor and Chris Burke\no Council assessment staff: Karen Hanratty and Ailsa Prendergast\n Final briefing to discuss council’s recommendation, 16 June 2020,\n9:30 am. Attendees:\no Panel members: Alison McCabe (Chair), Sandra Hutton, Marcia\nDoheny, Chris Burke and Kyle MacGregor\no Council assessment staff: Karen Hanratty, Ailsa Prendergast,\nAnthony Favetta, Andrew Roach, John Noakes, Steven Green","stage":"general","stage_basis":"heading","page":6},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":6},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the council assessment report","text":"C O N D I T I O N S O F C O N S E N T D a t e : 1 8 J u n e 2020\nDevelopment Application: 56271/2019\nProposed Development: NOMINATED INTEGRATED Residential 108 Bed Aged Care Facility\nStreet Address: LOT: 1 DP: 1261345, 88 Scaysbrook Drive KINCUMBER\nFormerly LOT: 103 DP: 707503, 290 Avoca Drive KINCUMBER\n1. PARAMETERS OF THIS CONSENT\n1.1. Approved Plans and Supporting Documents\nImplement the development substantially in accordance with the plans and supporting documents\nlisted below as submitted by the applicant and to which is affixed a Council stamp \"Development\nConsent\" unless modified by any following condition.\nArchitectural Plans by: Jackson Teece - Project No. 253824\nDrawing Description Issue Date\n253824-KI-AD-000-00 Cover Sheet 3 18/03/2020\n253824-KI-AD-000-01 Locality Plan 2 02/10/2019\n253824-KI-AD-000-02 Site Analysis 2 02/10/2019\n253824-KI-AD-000-03 Site Plan 2 02/10/2019\n253824-KI-AD-200-00 Lower Ground Floor Plan 3 18/06/2020\n253824-KI-AD-200-01 Ground Floor Plan 3 18/06/2020\n253824-KI-AD-301-00 Floor Plan - First Floor 3 18/06/2020\n253824-KI-AD-302-00 Floor Plan - Second Floor 3 18/06/2020\n253824-KI-AD-303-00 Floor Plan - Roof 2 18/06/2020\n253824-KI-AD-400-00 Elevations with Trees 2 02/10/2019\n253824-KI-AD-400-01 Elevation 2 02/10/2019\n253824-KI-AD-500-00 Sections 3 18/03/2020\n253824-KI-AD-501-00 Sections 1 18/03/2020\n253824-KI-AD-900-02 Shadow Diagrams Sheet 1 2 02/10/2019\n253824-KI-AD-900-03 Shadow Diagrams Sheet 2 2 02/10/2019\n253824-KI-AD-900-04 Shadow Diagram Sheet 3 2 02/10/2019\n253824-KI-AD-900-05 Shadow Diagram Sheet 4 2 02/10/2019\n253824-KI-AD-900-06 Shadow Diagram Sheet 5 2 02/10/2019\n253824-KI-AD-900-07 Shadow Diagram Sheet 6 2 02/10/2019\n253824-KI-AD-900-31 Area Plans - FSR Calculation (SEPP\nHPSD 2004)\n2 02/10/2019\n253824-KI-AD-900-54 8m Building Height Limit (SEPP HPSD\n2004)\n2 02/10/2019\nSCHEDULE 2\n253824-KI-AD-900-60 Material Selection 1 18/06/2020\nLandscape Design Report: Aspect Studios - Job No. B17035\nDrawing Description Issue Date\nB17035 Cover Sheet G 26/02/2020\nB17035 - SK1.0 Overview G 25/10/2019\nB17035 - SK2.0 House A, B and C to F G 25/10/2019\nB17035 - SK3.0 House A G 25/10/2019\nB17035 - SK3.1 House B G 26/02/2020\nB17035 - SK3.2 House C - F B 25/10/2019\nB17035 - SK6.0 Landscape Elements D 25/10/2019\nB17035 - SK6.1 Landscape Elements D 25/10/2019\nB17035 - SK6.2 Landscape Elements D 25/10/2019\nB17035 - SK7.0 Fence Design F 25/10/2019\nB17035 - SK8.0 Existing Tree Survey F 25/10/2019\nB17035 - SK8.1 Existing Tree Survey - Zone E3 F 25/10/2019\nB17035 - SK8.2 Tree Assessment Su mmary: On-site E 25/10/2019\nB17035 - SK8.3 Tree Assessment Su mmary - Zone E3 F 25/10/2019\nB17035 - SK8.4 Tree Assessment Su mmary - Zone E3 F 25/10/2019\nB17035 - SK9.0 Planting Design - Preliminary Planting\nSchedule\nD 25/10/2019\nB17035 - SK9.1 Planting Design - Preliminary Planting\nSchedule\nD 25/10/2019\nB17035 - SK9.2 Planting Design - Courtyard Palette D 25/10/2019\nB17035 - SK9.3 Planting Design - Courtyard Palette D 25/10/2019\nB17035 - SK9.4 Planting Design - Perimeter Palette D 25/10/2019\nB17035 - SK9.5 Planting Design - Perimeter Palette D 25/10/2019\nB17035 - SK9.6 Planting Desi gn - Perimeter Palette &\nStreet Trees\nD 25/10/2019\nB17035 - SK9.7 Planting Design - Na tive Buffer Palette D 25/10 /2019\nB17035 - SK10.0 General Specification Notes D 25/10/2019\nSupporting Documentation\nDocument Prepared by Date\nAir Quality Management Sub\nPlan\nLend Lease, Rev 3 5 August 2019\nArboricultural Impact Report La ndscape Matrix Pty Ltd 25 Octobe r 2019\nBCA & Accessibility Statement of\nCompliance\nBlackett Maguire & Goldsmith 27 March 2019\nBushfire Protection Assessment Travers Bushfire & Ecology, Ref:\n18LEND13\n27 March 2019\nCatholic Healthcare- Social\nHousing Provider Status\nCatholic Healthcare 31 January 2019\nCatholic Healthcare Palliative\nCare Confirmation\nCatholic Healthcare 24 January 2019\nGeotechnical Report Douglas P artners, Ref: 91006.00 15 November 2016\nNoise and Vibration\nManagement Plan\nLendLease, Rev 1 25 October 2019\nSoil and Water Management\nPlan\nWood & Grieve Engineers now part\nof Stantec, Ref: 30916-5\n15 October 2019\nTraffic Parking and Access\nReport\nSeca Solution, Ref P0660 26 March 2019\nWaste Management Plan Wast e Audit and Consultancy\nServices\nFebruary 2018\nSite Stormwater Management\nPlan\nWood & Grieve Engineers, Ref:\n30916-5-SYD-C\n29 January 2018\nCivil Engineering Plans Wood & Grieve Engineers\n1.2. Carry out all building works in accordance with the National Construction Code Series, Building\nCode of Australia, Volume 1 and 2 as appropriate.\n1.3. Comply with the General Terms of Approval / requirements from the Authorities as listed below\nin this consent.\nGovernment\nAgency /\nDepartment /\nAuthority\nDescription Ref No Date\nNSW Rural Fire\nService\nGeneral Terms of Approval\n/ Bushfire Safety Authority\nD18/6056\nDA18062113616 CC","stage":"general","stage_basis":"heading","page":6},{"label":"13","code":null,"number":"13","title":"March 2019","text":"Natural Resources\nAccess Regulator\nGeneral Terms of Approval IDAS1114380 15 May 2019\n1.4. No buildings, structures or ancillary development associated with the Residential Aged Care\nFacility is to occur on the part of the site zoned E3 Environmental Management under Gosford\nLocal Environmental Plan 2014.\n2. PRIOR TO ISSUE OF ANY CONSTRUCTION CERTIFICATE\n2.1. All conditions under this se ction must be met prior to the issue of any Construction Certificate.\n2.2. Submit to the Principal Ce rtifier details showing that the development complies with the\nGeneral Terms of Approval/Bush Fire Safety Authority, Reference D18/6056 DA18062113616\ndated 13 March 2019 issued by the NSW Rural Fire Service.\n2.3. Submit details to the Principal Certifier for the design o f the advertising signage in accordance\nwith Section 3.3.3 of the Department of Planning and Infrastructure's Transport Corridor\nOutdoor Advertising and Signage Guidelines (November 2017) - Illumination and reflectance.\nThe signage shall meet the illumination requirements for Zone 4 areas.\n2.4. Undertake further investigation works as required by the geotechnical report(s) listed as\nsupporting documentation in this development consent and submit to the Principal Certifier an\naddendum/amended geotechnical report. The geotechnical report shall address the proposal\ndesign in accordance with the plans listed in Condition 1.1.\n2.5. Submit an application to C ouncil under Section 305 of the Water Management Act 2000 to\nobtain a Section 307 Certificate of Compliance. The Application for a 307 Certificate under\nSection 305 Water Management Act 2000 form can be found on Council’s website\nwww.centralcoast.nsw.gov.au. Early application is recommended.\nA Section 307 Certificate must be obtained prior to the issue of any Construction Certificate.\n2.6. Submit an application to Council under section 138 of the Roads Act 1993 for the approval of\nrequired works to be carried out within the road reserve.\nSubmit to Council Engineering plans for the required works within a public road that have been\ndesigned by a suitably qualified professional in accordance with Council’s Civil Works\nSpecification and Chapter 6.3 - Erosion Sedimentation Control of the Gosford Development\nControl Plan 2013. The Engineering plans must be included with the Roads Act application for\napproval by Council.\nDesign the required works as follows:\nAvoca Drive\na) Road works on the southern side of Avoca Drive within the site frontage from the section of\nthe site frontage between the fire trail access to the existing kerb and gutter associated\nwith the pedestrian refuge in Avoca Drive. Works to include kerb and guttering, subsoil\ndrainage, footpath formation, drainage, street tree planting and road pavement.\nb) Road works on the northern side of Avoca Drive between the bus stop and the pedestrian\nrefuge in Avoca Drive. Works to include kerb and guttering, subsoil drainage, footpath\nformation, drainage and road pavement.\nc) Footway formation on the northern side of Avoca Drive with a minimum width of 2.5m\ngraded at +2% from the top of kerb towards the property boundary, from the bus stop to\nthe pedestrian refuge in Avoca Drive. Existing vehicle crossings to be adjusted and\nreconstructed where required.\nd) Formalisation of the bus stops located at the frontage of the site on both the southern and\nnorthern side of Avoca Drive.\ne) 1.5m wide reinforced (SL72 steel fabric, 100mm thick) concrete footpath on the southern\nside of Avoca Drive in an approved location across the frontage of the site from the eastern\nmost pedestrian access (near the emergency fire trail) to the western frontage of the site.\nThe footpath is to connect to the pedestrian refuge.\nf) 1.5m wide reinforced (SL72 steel fabric, 100mm thick) concrete footpath on the northern\nof Avoca Drive behind the kerb from the bus stop to the pedestrian refuge in Avoca Drive.\nThe footpath is to connect to the pedestrian refuge.\ng) Heavy-duty vehicle crossing in Avoca Drive associated with the access to the existing\nemergency fire trail that has a width to accommodate the swept turn paths of the RFS\nvehicle and constructed with 200mm thick concrete reinforced with 1 layer of SL72 steel\nfabric top and bottom.\nh) All redundant vehicular crossings in Avoca Drive are to be removed and footway formation\nreinstated.\ni) roadside furniture and safety devices as required eg. fencing, signage, guide posts,\nchevrons, directional arrows, and/or guard rail in accordance with Transport for NSW\n(TfNSW) and relevant Australian Standards.\nj) Erosion and sedimentation control plan.\nScaysbrook Drive\nk) Footway formation within the frontage of the site in Scaysbrook Drive graded at +2% from\nthe top of kerb to the property boundary, from the existing footpath on the eastern side of\nthe site frontage to proposed “fire hydrant, sprinkler, and booster assembly” located on\nthe western side of the proposed vehicle crossing.\nl) Reinforced (SL72 steel fabric, 100mm thick) concrete footpath within the frontage of site in\nScaysbrook Drive from the existing footpath on the eastern side of the site frontage to\nproposed “fire hydrant, sprinkler, and booster assembly” located on the western side of\nthe proposed vehicle crossing.\nm) Heavy-duty vehicle crossing in Scaysbrook Avenue Avoca Drive that has a width of 6m at\nthe boundary and splayed to the kerb line, and constructed with 200mm thick concrete\nreinforced with 1 layer of SL72 steel fabric top and bottom.\nn) All redundant vehicular crossings in Scaysbrook Drive are to be removed and footway\nformation reinstated.\no) the piping of stormwater from within the site to Council’s drainage system located in\nScaybrook Drive.\np) Removal of a tree adjacent to the western side of the vehicle access crossing in Scaysbrook\nDrive to improve sight distance to comply with AS2890.\nq) Erosion and sedimentation control plan.\nThe Roads Act application must be approved by Council prior to commencing works in the road\nreserve.\nA fee for the approval of engineering plans under the Roads Act 1993 applies. The amount of\nthis fee can be obtained by contacting Council’s Customer Service Centre on\n1300 463 954.\n2.7. Submit a dilapidation report to Council with the Roads Act application and / or Construction\nCertificate application. The report must document and provide photographs that clearly depict\nany existing damage to the road, kerb, gutter, footpath, driveways, street trees, street signs or\nany other Council assets in the vicinity of the development. The dilapidation report may be\nupdated with the approval of the Principal Certifying Authority prior to the commencement of\nworks.\n2.8. Submit design details of the following engineering works w ithin private property:\na) Driveways / ramps and car parking areas must be designed according to the requirements\nof Australian Standard AS 2890: Parking Facilities for the geometric designs, and industry\nStandards for pavement designs\nb) Nutrient/pollution control measures must be designed in accordance with Chapter 6.7 -\nWater Cycle Management of the Gosford Development Control Plan. A nutrient / pollution\ncontrol report including an operation and maintenance plan must accompany the design.\nc) On-site stormwater retention measures must be designed in accor\ndance with Chapter 6.7 -\nWater Cycle Management of the Gosford Development Control Plan 2013. A report\ndetailing the method of stormwater harvesting, sizing of retention tanks for re-use on the\nsite and an operation and maintenance plan must accompany the design\nd) Piping of all stormwater from impervious areas within the site to Council’s drainage system\nlocated in Scaysbrook Drive.\nThese design details and any associated reports must be included in the Construction\nCertificate. No fencing of the bio-retention basin is permitted and that should be reflected in\nthe design detail of the basin.\n2.9. Submit engineering details prepared and certified by a pra ctising structural engineer that\ncomply with Council’s Building Over or Adjacent to Sewer and Water Main Guidelines to the\nsatisfaction of Council. Engineering details must be submitted to Council’s Water Assessment\nTeam for approval. Plan assessment fees apply.\n2.10. The developer shall enter into a Works Authorisation Deed (WAD) with Transport for NSW\n(TfNSW)) prior to the approval of any Roads Act application for works within Avoca Drive.\nThe WAD process, including acceptance of design documentation and construction, can take\ntime. The developer should be aware of this and allow sufficient lead time within the project\ndevelopment program to accommodate this process. It is therefore suggested that the\ndeveloper work through this process as soon as possible with the TfNSW.\n2.11. Submit a pavement investigation and report prepared by a practising Geotechnical Engineer for\nthe road works. This report must be submitted with the Construction Certificate application or\napplication for work under the Roads Act 1993.\nThe pavement depths must be determined in accordance with Council’s specifications and the\nfollowing traffic loadings:\nName of Street Traffic Loading (ESAs)\nAvoca Drive To be advised by TfNSW\n2.12. Submit details to the Princi pal Certifier of the design of the fit out of the food premises. The\ndesign of the fit out of the food premises is to comply with the Food Act 2003, Food Regulation\n2010, Australia New Zealand Food Standards Code, Australian Standard AS 4674-2004: Design,\nConstruction and Fit-out of Food Premises and Clause G1.2 of the National Construction Code\nSeries, Building Code of Australia, Volume 1 and 2 as appropriate. Details of compliance are to\nbe included in the plans and specifications for the Construction Certificate.\n2.13. Submit details to the Principal Certifier of any proposed mechanical ventilation systems. The\ndesign of the mechanical ventilation is to comply with the relevant requirements of Clause F4.12\nof the National Construction Code Series, Building Code of Australia, Volume 1 and 2 as\nappropriate, Australian Standard AS 1668.1:2015 The use of ventilation and air conditioning in\nbuildings - Fire and smoke control in buildings and Australian Standard 1668.2:2012 The use of\nventilation and air conditioning in buildings - Mechanical ventilation in buildings\n(including\nexhaust air quantities and discharge location points). These details are to be included in the\nConstruction Certificate.\n2.14. All trees shown on the E3 z oned land are to be retained. All land within the identified E3 -\nEnvironmental Management Zone is to be identified as a ‘No Go Area’, with no works to be\nundertaken within this area.\n2.15. Submit to Council for approval an amended Landscape Desig n Report (the plan) that must be\nupdated to include the following information:\na) Design details that clearly identify the proposed palette, and specific location and quantity\nof individual tree species and mature tree heights including:\ni. Larger canopy trees selected from the native buffer tree palette (or equivalent) sited\nmid-slope of the site that encompasses the area from the Scaysbrook Drive frontage\nto House B and blending from above the bio-retention basin and adjoining the access\ndriveway to the lower edge of House A courtyard.\nii. A 10m width of native buffer palette planting including larger canopy trees within the\nsite along the full Scaysbrook Drive frontage, including behind the service enclosures\nfacing Scaysbrook Drive. If 10m width is not possible behind the service enclosures\ndue to the bioretention basin, identify alternative native buffer palette planting areas\nto contribute to native streetscape presentation.\niii. Mounding adjacent the western boundary so that water flows are directed over the\nsite to the street and not towards the western property at 90 Scaysbrook Drive.\niv. Cross-sections and mounding details including RLs.\nb) Indicate the location and details of all retaining walls on the site including RLs, wall heights\nand cross-sections.\nc) Provide a minimum of 4 street trees along the Avoca Drive frontage. The location of the\nstreet tree planting is to have regard to existing infrastructure in the road reserve and the\nproposed the pedestrian pathway.\nd) No tree clearing in the E3 Environmental Management Zone.\ne) Retain trees numbered 14, 15, 16 and 17 as identified in the Arboricultural Impact Report\nprepared by Landscape Matrix Pty Ltd dated 25 October 2019:\ni. Provide design details of the building/retaining structures footings adjacent these\ntrees (e.g. pier and beam construction).\nii. Provide ongoing measures for protection of these trees as identified in the\nArboricultural Impact Report and as required by conditions of this consent.\nf) Integration of the bio-retention basin into the landscape without the need for fencing\naround the basin.\nThe Landscape Design Report must be endorsed by an accredited Bushfire Consultant indicating\nthe plan is consistent the Asset Protection Zone requirements of the General Terms of\nApproval/Bushfire Safety Authority issued by the NSW Rural Fire Service for the development.\nThe amendments to the Landscape Design Report shall be consistent with the marked-up plans\nsubmitted on 16 June 2020 to the Hunter and Central Coast Regional Planning Panel as follows:\n Architectural Plan by Jackson Teece - Ground Floor Plan 253824-K1-AD-200-01 Issue 2\nmarked up with the retaining wall extent and heights dated 15 June 2020.\n Landscape Design Report by Aspect Studios with comments included in B17035 SK 2.0\nRev G covering mound/bund tree heights and B17035 SK3.0 Rev G covering the northern\nboundary tree heights at maturity.\n2.16. The bio-retention basin is to be provided on site and int egrated into the landscape setting\nwithout the need for any fencing. No approval is granted for any fencing.\n3. PRIOR TO COMMENCEMENT OF ANY WORKS\n3.1. All conditions under this se ction must be met prior to the commencement of any works.\n3.2. No activity is to be carried out on-site until the Construction Certificate has been issued, other\nthan;\na) Site investigation for the preparation of the construction, and / or\nb) Implementation of environmental protection measures, such as erosion control and the\nlike that are required by this consent\nc) Demolition approved by this consent.\n3.3. Appoint a Principal Certifier for the building work:\na) The Principal Certifier (if not Council) is to notify Council of their appointment and notify\nthe person having the benefit of the development consent of any critical stage inspections\nand other inspections that are to be carried out in respect of the building work no later\nthan two (2) days before the building work commences.\nb) Submit to Council a Notice of Commencement of Building Work form giving at least two (2)\ndays’ notice of the intention to commence building work. The forms can be found on\nCouncil’s website www.centralcoast.nsw.gov.au\n3.4. Erect a sign in a prominent position on any work site on w hich building, subdivision or\ndemolition work is being carried out. The sign must indicate:\na) The name, address and telephone number of the principal certifying authority for the work;\nand\nb) The name of the principal contractor and a telephone number at which that person can be\ncontacted outside of working hours; and\nc) That unauthorised entry to the work site is prohibited.\nd) Remove the sign when the work has been completed.\n3.5. Submit both a Plumbing and Drainage Inspection Application , with the relevant fee, and a\nPlumbing and Drainage Notice of Work in accordance with the Plumbing and Drainage Act 2011\n(to be provided by licensed plumber). These documents can be found on Council’s website at:\nwww.centralcoast.nsw.gov.au.\nContact Council prior to submitting these forms to confirm the relevant fees.\n3.6. Apply for and obtain a Controlled Activity Approval from t he Natural Resources Access\nRegulator (NRAR) prior to commencement of any work or activity.\nAdvice from NRAR:\nA completed application form must be submitted to NRAR together with any required plans,\ndocuments, application fee and proof of Council’s development consent. Finalisation of an\napproval can take up to eight (8) weeks from the date of the application and all required\nsupporting documentation is received.\nApplication forms are availabl e from the NRAR website at:\nhttps://www.industry.nsw.gov.au/water/licensing-trade/approvals/controlled-activities\n3.7. Submit to the Principal Cert ifier a Traffic and Pedestrian Management Plan (for works internal of\nthe site) prepared by a suitably qualified professional.\nThe Plan must be prepared in consultation with Council, and where required, the approval of\nCouncil’s Traffic Committee obtained.\nThe Plan must address, but not be limited to, the following matters:\n ingress and egress of vehicles to the Subject Site\n loading and unloading, including construction zones\n predicted traffic volumes, types and routes\n pedestrian and traffic management methods, and\n other relevant matters\nThe Applicant must submit a copy of the final Plan to Council, prior to the commencement of\nwork.\n3.8. Submit to the Principal Certifier a Construction Environme ntal Management Plan (CEMP),\nincluding a Traffic Management Plan (CTMP), Vehicle Movement Plan and Traffic Control Plan.\nThe CEMP shall be prepared with the intention of causing minimal impact on the environment\nand operation of the road network during construction of the development.\nThe Construction Environmental Management Plan is to provide for:\n Emergency response plan (pollution incident)\n Waste and stockpiling management plan\n Erosion and sediment control plan\n Delivery and storage of materials\n Worker’s parking and amenities\n Hours of construction\n Noise and dust mitigation\n Process of handling complaints\n Crane permits (crane location plan)\n Describe the volume and type of traffic generated by the works including designed routes\n Include measures to maintain the safe and efficient operation of the surrounding road\nnetwork.\n The Traffic Control Plan shall be prepared and implemented by a suitably qualified RMS\naccredited person to ensure safe legal and practical ingress and egress of vehicles to and\nfrom the site.\n Any proposed Construction zones within Councils Road Reserves. Note: The “Construction\nZones” require separate application and approval from Council.\nThis plan shall have regard to Conditions 3.7 & 4.18 of this consent.\nThe Applicant must submit a copy of the final Plan to Council, prior to the commencement of\nwork.\n3.9. Erect a temporary hoarding or temporary construction site fence between the work site and\nadjoining lands before the works begin and must be kept in place until after the completion of\nthe works, if the works:\na) could cause a danger, obstruction or inconvenience to pedestrian or vehicular traffic, or\nb) could cause damage to adjoining lands by falling objects, or\nc) involve the enclosure of a public place or part of a public place.\nNote 1: A structure on public land or on or over a public road requires the prior approval of the\nrelevant authority under the Local Government Act 1993 or the Roads Act 1993, respectively.\nNote 2: The Work Health and Safety Act 2011 and Work Health and Safety Regulation 2011\ncontain provisions relating to scaffolds, hoardings and other temporary structures.\n3.10. Provide or make available toilet facilities at the work site before works begin and maintain the\nfacilities until the works are completed at a ratio of one toilet plus one additional toilet for every\ntwenty (20) persons employed at the site.\nEach toilet must:\na) be a standard flushing toilet connected to a public sewer, or\nb) have an on-site effluent disposal system approved under the Local Government Act 1993,\nor\nc) be a temporary chemical closet approved under the Local Government Act 1993.\n3.11. Provide certification to th e Principal Certifier that the structural engineer's details have been\nprepared in accordance with the recommendations of the geotechnical report(s) listed as\nsupporting documentation in this development consent.\n3.12. Install a temporary fence around the identified ‘No Go Area’ (E3 - Environmental Management\nZone).\nAll fenced conservation areas are to be clearly marked as a \"No Go Area\" on the fencing itself.\nNo clearing of vegetation, storage of vehicles or machinery, stockpiling, materials storage or\nunauthorised access is to occur within the fenced conservation area.\n3.13. Ensure that all parties / tr ades working on the site are fully aware of their responsibilities with\nrespect to tree protection conditions.\n3.14. Trees to be retained are to be protected by fencing and / or other accepted protection\nmeasures in accordance with Australian Standard AS 4970-2009: Protection of Trees on\nDevelopment Sites and in accordance with Section 7, Tree Protection Measures of the\nArboricultural Impact Report by Landscape Matrix Pty Ltd, dated 25 October 2019. All required\ntree protection measures are to be maintained for the duration of construction works.\nSign-post fences around Tree Protection Zones to warn of its purpose.\n4. DURING WORKS\n4.1. All conditions under this se ction must be met during works.\n4.2. Carry out construction (including earthworks) or demolitio n works during the construction\nphase of the development only between the hours as follows:\n Monday to Friday: 7am to 6pm\n Saturday: 8am to 1pm\nNo construction or demolition works associated with the development are permitted to be\ncarried out at any time on a Sunday or a public holiday.\n4.3. Place all building materials, plant and equipment on the site of the development during the\nconstruction phase of the development so as to ensure that pedestrian and vehicular access\nwithin adjoining public roads, footpaths and reserve areas, is not restricted and to prevent\ndamage to public infrastructure. Further, no construction work is permitted to be carried out\nwithin the road reserve unless the works are associated with a separate approval issued under\nthe provisions of the Roads Act 1993.\n4.4. During the construction phase of the development, if any A boriginal object (including evidence\nof habitation or remains) is discovered during the course of the work:\na) All excavation or disturbance of the area must stop immediately in that area, and\nb) The Office of Environment & Heritage must be advised of the discovery in accordance with\nsection 89A of the National Parks and Wildlife Act 1974.\nNote: If an Aboriginal object is discovered, an Aboriginal heritage impact permit may be\nrequired under the National Parks and Wildlife Act 1974.\n4.5. Keep a copy of the stamped approved plans on-site for the duration of site works and make the\nplans available upon request to either the Principal Certifying Authority or an officer of Council.\n4.6. Notify Council when plumbing and drainage work will be rea dy for inspection(s) and make the\nwork accessible for inspection in accordance with the Plumbing and Drainage Act 2011.\n4.7. Submit a report prepared by a registered Surveyor to the P rincipal Certifier at each floor level of\nconstruction of the building (prior to the pouring of concrete) indicating that the finished floor\nlevel is in accordance with the approved plans. A compilation of these reports is to be provided\nto Council at completion of the Occupation Certificate.\n4.8. Cease all excavation works if acid sulfate soils are identified until such time as details of\nmitigation and treatment measures are submitted to, and approved by, the Principal Certifier.\n4.9. Implement all recommendations of the geotechnical report(s ) listed as supporting\ndocumentation in this development consent and where modified by conditions of consent.\nFurthermore, the geotechnical engineer must provide written certification to the Principal\nCertifier that all works have been carried out in accordance with the recommendations\ncontained within the geotechnical report(s).\n4.10. All works associated with th e subject development shall be undertaken at full cost to the\ndeveloper and at no cost to Transport for NSW or Council, and to Council’s requirements.\n4.11. Maintain the temporary fenc e around identified ‘No Go Area’ (E3 - Environmental Management\nZone). The fence must be maintained for the duration of construction works.\n4.12. Undertake clearing in accordance with the approved Arbori cultural Impact Assessment Report\n(Landscape Matrix, 25/10/19). Trees must be removed in such a manner so as to prevent\ndamage to surrounding trees to be retained.\n4.13. Manage native fauna appropr iately during clearing and construction phase of the approved\nworks. In this regard, an appropriately licensed Fauna Ecologist is to be engaged to advise and\nsupervise the clearing of trees. Where, in spite of precautions, wildlife is injured, the Fauna\nEcologist is to take the necessary action to treat the animal, which may include veterinary\ntreatment or transfer of the animal to a volunteer wildlife carer group such as WIRES or Wildlife\nArc.\n4.14. Utilise timber from felled native trees by:\n Re-instating logs as ground habitat in areas of retained vegetation, and/or\n Wood chip or tub grind into mulch for landscaping, soil stabilisation or bush regeneration,\nand/or\n Using for firewood (but not piled burned on-site); and/or\n Recycling for use in construction materials, furniture or fencing.\n4.15. Undertake the removal of an y tree located on Council managed land due to works approved by\na Development Application at the full cost and responsibility of the developer / owner using a\nPre-qualified Tree Contractor.\nContact Central Coast Council on 1300 463 954 for the current list of relevant contractors.\n4.16. Ensure a qualified arborist (AQF 5) is on-site to oversee the works in relation to tree protection\nmeasures during critical stages of construction.\nN o t e :\nActivities generally excluded fr om the Tree Protection Zone, but not limited to:\n Machine excavation, trenching, material storage, prepare chemicals or cement, park,\nrefuel, dump waste, wash down, fill or change soil level.\n4.17. Re-use, recycle or dispos e of all building materials during the demolition and construction phase\nof the development in accordance with the Waste Management Plan signed by Waste Audit and\nConsultancy Services, dated February 2018.\n4.18. Conduct earthworks and cons truction activities in accordance with the following documents:\n Noise and vibration management plan Revision 1 dated 25 October 2019 prepared by\nLendlease.\n Air quality management subplan Revision 3 dated 5 August 2019 prepared by Lendlease.\n4.19. Implement all soil and wate r management control measures and undertake works in\naccordance with the approved Soil and Water Management Plan ref: 30916-5 prepared by\nWood and Grieve Engineers dated 15 October 2019. Update the plan as required during all\nstages of the construction or in accordance with the ‘Blue Book’ (Managing Urban Stormwater:\nSoils and Construction, Landcom, 2004).\n4.20. No fill other than that as i ndicated within the approved plans is permitted to be placed upon the\nsite.\n4.21. No filling or debris shall be placed within any watercourse or drain.\n4.22. No soils to be imported to the subject site except for Vi rgin Excavated Natural Material (VENM)\nas defined in Schedule 1 of the Protection of the Environment Operations Act 1997.\n4.23. Classify all excavated mater ial removed from the site in accordance with NSW EPA Waste\nClassification Guidelines prior to disposal. All excavated material must be disposed of to an\napproved waste management facility except where it meets the NSW EPA Resource Recovery\nExemptions, and receipts of the disposal must be kept on-site.\n4.24. Arrange with the relevant service provider / Authority (e g. Ausgrid, Jemena, communications\nprovider) for the supply of services concurrently with the engineering work approved by this\nconsent. Arrangements must include, where required, any relocation of existing mains and\nservices, and dedication of easements for mains and services.\n5. PRIOR TO ISSUE OF ANY OCCUPATION CERTIFICATE\n5.1. All conditions under this se ction must be met prior to the issue of any Occupation Certificate.\n5.2. Prior to the occupation or use of the building/structure, an application for an Occupation\nCertificate for the development must be submitted to and approved by the Principal Certifier.\nThe Occupation Certificate application is to satisfy all of the requirements of the Environmental\nPlanning and Assessment Regulation 2000.\n5.3. Complete the building in accordance with the relevant prov isions and requirements of the\nNational Construction Code Series.\n5.4. Submit a Certificate of Co mpliance for all plumbing and drainage work and a Sewer Service\nDiagram showing sanitary drainage work (to be provided by licensed plumber) in accordance\nwith the Plumbing and Drainage Act 2011.\n5.5. Provide the Principal Certifier with written certification from a recognised Bushfire Consultant\ncertifying the development has been completed in accordance with the General Terms of\nApproval/Bush Fire Safety Authority, Reference D18/6056 DA18062113616 dated 13 March\n2019 issued by the NSW Rural Fire Service.\n5.6. Complete the landscaping wo rks in accordance with the approved landscape plan/landscape\ndesign report.\n5.7. Provide the Principal Certifier with written certification from a qualified landscape designer\ncertifying that landscaping has been implemented in accordance with the approved landscape\nplan as amended by any conditions of this consent.\n5.8. Provide certification from a geotechnical engineer to the Principal Certifier that all works have\nbeen carried out in accordance with the recommendations contained within the geotechnical\nreport(s) listed as supporting documentation in this development consent.\n5.9. Revegetate and st abilise all areas disturbed by construction activities associated with the\ndevelopment so as to prevent erosion and dust nuisance occurring.\n5.10. Execute an instrument under the Conveyancing Act 1919 for the following restrictive covenants\nwith Council having the benefit of these covenants and having sole authority to release and\nmodify.\nThe approved development is only to be occupied by:\na) people aged 55 years or over or people with a disability as defined by the provisions of\nState Environmental (Housing for Seniors or People with a Disability) 2004\nb) people who live with such people as defined in sub-clause above; and\nc) staff employed to assist in the administration of and provision of services to housing\nprovided in this development.\n5.11. Implement the following Crim e Prevention through Environmental Design (CPTED) principles\nand strategies to minimise the opportunity for crime:\na) provide adequate lighting to common areas as required under Australian Standard AS\n1158: Lighting for roads and public spaces\nb) design of landscaping, adjacent to mailboxes and footpaths, must not provide concealment\nopportunities for criminal activity\nc) design the development to avoid foot holes or natural ladders so as to minimise unlawful\naccess to the premises\nd) provide signage within the development to identify all facilities, entry / exit points and\ndirect movement within the development\n5.12. Construct any additional civil works, where required by C ouncil, to ensure satisfactory\ntransitions to existing site formations and pavements where designs contained in the Roads Act\nWorks Approval do not adequately address transition works.\n5.13. Complete construction of th e stormwater management system in accordance with the\nStormwater Management Plan and Australian Standard AS 3500.3-Stormwater drainage\nsystems. Certification of the construction by a suitably qualified consultant must be provided to\nthe Principal Certifier.\n5.14. Complete works within the r oad reserve in accordance with the approval under the Roads Act\n1993. The works must be completed in accordance with Council’s Civil Works Specification and\nChapter 6.3 - Erosion Sedimentation Control of the Gosford Development Control Plan 2013.\nDocumentary evidence for the acceptance of such works must be obtained from the Roads\nAuthority.\n5.15. Repair any damage to Counc il’s infrastructure and road reserve as agreed with Council. Damage\nnot shown in the dilapidation report submitted to Council before the development works had\ncommenced will be assumed to have been caused by the development works unless the\nDeveloper can prove otherwise.\n5.16. Complete the civil engineering works within the developme nt site in accordance with the\ndetailed design drawings and design reports/plans within the construction certificate.\n5.17. Amend the Deposited Plan (DP) to:\n include an Instrument under the Conveyancing Act 1919 for the following restrictive\ncovenants; with Council having the benefit of these covenants and having sole authority to\nrelease and modify. Wherever possible, the extent of land affected by these covenants\nmust be defined by bearings and distances shown on the plan\na) create a Restriction as to use of land over all lots containing a nutrient / pollution\nfacility restricting any alteration to such facility or the erection of any structure over\nthe facility or the placement of any obstruction over the facility\nAnd,\n include an instrument under the Conveyancing Act 1919 for the following positive\ncovenants; with Council having the benefit of these covenants and having sole authority to\nrelease and modify. Contact Council for wording of the covenant(s)\na) to ensure on any lot containing a nutrient / pollution facility that:\n(i) the facility will remain in place and fully operational\n(ii) the facility is maintained in accordance with the operational and maintenance\nplan so that it operates in a safe and efficient manner\n(iii) Council’s officers are permitted to enter the land to inspect and repair the facility\nat the owners cost\n(iv) Council is indemnified against all claims of compensation caused by the facility\nSubmit to the Principal Certifying Authority copies of registered title documents showing the\nrestrictive and positive covenants.\n5.18. All road works under the WAD entered into with Transport for NSW shall be completed prior to\nissuing any Occupation Certificate for the development.\n5.19. Provide certification to the Principal Certifier to confi rm the final fit-out of the premises\ncomplies with the Food Act 2003, Food Regulation 2010, Australia New Zealand Food Standards\nCode, Australian Standard AS 4674-2004: Design, Construction and Fit-out of Food Premises and\nClause G1.2 of the National Construction Code Series, Building Code of Australia, Volume 1 and\n2 as appropriate.\n5.20. No food handling, as defined by the NSW Food Act 2003, is permitted in the food premises prior\nto the issue of the Occupation Certificate.\n5.21. Provide certification from a mechanical engineer to the Principal Certifier that the construction,\ninstallation and operation of the exhaust hood ventilation system meet the requirements of:\n Australian Standard AS 1668 Part 1-2015: The use of ventilation and air-conditioning in\nbuildings - Fire and smoke control in buildings\n Australian Standard AS 1668 Part 2-2012: The use of ventilation and air-conditioning in\nbuildings - Mechanical ventilation in buildings\n5.22. Submit a Food Premises registration form to Council. The form can be found on Council’s\nwebsite: www.centralcoast.nsw.gov.au\n5.23. Submit an emergency evacuati on plan prepared by the operators to Council.\n6. ONGOING OPERATION\n6.1. Provide a minibus service to residents on a regular basis for organised events and activities.\n6.2. Load and unload delivery ve hicles wholly within the site.\n6.3. All vehicles shall enter and exit the site in a forward di rection.\n6.4. Maintain all security/front /perimeter fencing for the life of the development in the approved\nlocation.\n6.5. Operate and maintain all ex ternal lighting so as not to impact on any adjoining property.\n6.6. Maintain the entire propert y as an Inner Protection Area (IPA) as outlined within section 4.1.3\nand Appendix 5 of ‘Planning for Bush Fire Protection 2006’ and the NSW Rural Fire Service’s\ndocument ‘Standards for Asset protection zones’.\n6.7. Maintain all works associat ed with the approved Landscape Plans for the lifetime of the\ndevelopment.\n6.8. Replace all damaged, dead o r missing areas of lawn and plantings at the completion of the\nlandscaping maintenance period, including adjoining road reserve areas that are in a state of\ndecline, to a healthy and vigorous condition in accordance with the approved detailed\nLandscape Plans and Development Consent Conditions.\n6.9. Use external lighting that m inimises overspill into retained vegetated areas.\n6.10. Any proposed advertising sign must not have / use:\n Flashing lights or messages.\n Animated display, moving parts or simulated movement.\n Complex displays that hold a driver's attention beyond \"glance appreciation\".\n Displays resembling traffic signs or signals, or giving instruction to traffic by using words\nsuch as 'halt' or 'stop'.\n A method of illumination that distracts or dazzles.\n6.11. Maintain the illumination and reflectance of the signs in accordance with Section 3.3.3 of the\nDepartment of Planning and Infrastructure's Transport Corridor Outdoor Advertising and\nSignage Guidelines (November 2017) - Illumination and reflectance.\n6.12. Maintain the signs and means of fixing and support in a p resentable and structurally satisfactory\nstate of repair at all times.\n6.13. Do not erect third party ad vertisement on or in conjunction with the proposed development.\n6.14. Maintain the nutrient / po llution control facilities in accordance with the operation and\nmaintenance plan.\n6.15. Store all waste generated on the premises in a manner so that it does not pollute the\nenvironment.\n6.16. Transport all waste genera ted on the premises to a facility which is licensed to receive that\nmaterial.\n6.17. No obstructions t o the wheel out of the waste bins are permitted including grills, speed humps,\nbarrier kerbs, etc.\n6.18. Comply with all commitments as detailed in the Waste Management Plan signed by Waste Audit\nand Consultancy Services, dated February 2018.\n6.19. Locate the approved waste storage enclosure / area as ind icated on Project Number 253824-KI-\nAD-200-01 Revision 2, dated 2 October 2019, prepared by Jackson Teece.\n6.20. Construct and manage the wa ste storage enclosure in accordance with the provisions of\nGosford Development Control Plan 2013, Part 7: Chapter 7.2 - Waste Management, Appendix D\nand Appendix G, as applicable.\n6.21. Do not place or store waste material, waste product or wa ste packaging outside the approved\nwaste storage enclosure.\n6.22. Mixed and recyclable waste to be separated, stored in sealed containers and serviced by a\nprivate, commercial waste contractor consistent with swept turning path details in the report by\nSECA Solutions dated 26 March 2019, Attachment C - Swept Paths.\n6.23. Clinical waste to be stored in a secure location for serv icing by a specialist medical waste\ndisposal contractor.\n7. PENALTIES\nFailure to comply with this development consent and any condition of this consent may be a criminal\noffence. Failure to comply with other environmental laws may also be a criminal offence.\nWhere there is any breach Council may without any further warning:\n Issue Penalty Infringement Notices (On-the-spot fines);\n Issue notices and orders;\n Prosecute any person breaching this consent, and/or\n Seek injunctions/orders before the courts to retain and remedy any breach.\nWarnings as to Potential Maximum Penalties\nMaximum Penalties under NSW Environmental Laws include fines up to $1.1 Million and/or custodial\nsentences for serious offences.","stage":"general","stage_basis":"heading","page":9}]});
